fn decode_shift(s: Vec<char>) -> Vec<char> {
    // Define the ASCII value for 'a' so we can convert characters to a 0–25 range
    const A: u8 = b'a';
    // Amount to shift left
    const SHIFT: u8 = 5;
    // Iterate over each character, decode it, and collect back into a Vec<char>
    s.into_iter()
     .map(|c| {
         // Convert c to its 0–25 index
         let idx = (c as u8).wrapping_sub(A);
         // Apply a left shift of 5 with wrap‐around in [0, 25]
         let decoded_idx = (idx + 26 - SHIFT) % 26;
         // Convert back to a lowercase letter
         (A + decoded_idx) as char
     })
     .collect()
}

